<?php

namespace App\Ai\Agents;

use App\Ai\Exceptions\AgenteInativoException;
use App\Ai\Middleware\AiAuditMiddleware;
use App\Models\User;
use Illuminate\Support\Facades\Log;
use Laravel\Ai\Concerns\RemembersConversations;
use Laravel\Ai\Contracts\Conversational;
use Laravel\Ai\Contracts\HasTools;
use Stringable;

/**
 * Assistente conversacional embarcado no painel (widget `AssistenteChatWidget`).
 *
 * Instruções, provider/modelo e guardrails vêm do catálogo `agentes_ia` (slug
 * `assistente`), nunca hardcoded aqui — trocar o comportamento do assistente é editar
 * um registro no painel admin, não fazer deploy.
 *
 * Perfil ASSISTENTE: zero escrita. As tools que você registrar devem recuperar SOMENTE
 * o que o usuário logado pode ver — o filtro de permissão mora na query da tool, não na
 * instrução do modelo. O `User` é explícito no construtor porque o agente roda fora do
 * ciclo de request do painel (jobs, streaming) e não pode depender de `auth()`.
 */
final class Assistente extends AgenteBase implements Conversational, HasTools
{
    use RemembersConversations;

    public function __construct(public User $user) {}

    public function slug(): string
    {
        return 'assistente';
    }

    /**
     * Instruções do catálogo. Agente inativo → indisponibilidade honesta, nunca resposta
     * inventada. Agente ausente do catálogo → RuntimeException (classe base).
     */
    public function instructions(): Stringable|string
    {
        if (! $this->estaAtivo()) {
            Log::channel('ai')->warning(
                '[Assistente@instructions] Agente desativado no catálogo | slug: '.$this->slug(),
                ['ativo' => false, 'versao' => $this->agente()->versao],
            );

            throw new AgenteInativoException("Agente [{$this->slug()}] está indisponível no momento.");
        }

        return parent::instructions();
    }

    /**
     * Guardrails do catálogo (fail-closed se vazios — classe base) + auditoria por ÚLTIMO,
     * para que o prompt logado já esteja mascarado pelo redator de PII.
     *
     * @return list<object>
     */
    public function middleware(): array
    {
        return [...parent::middleware(), new AiAuditMiddleware];
    }

    /**
     * Tools do agente: o mapa abaixo é o que EXISTE no código; a coluna `agentes_ia.tools`
     * é a allowlist do que está LIBERADO. Só o que está nos dois roda — liberar uma tool
     * vira edição de registro no painel, não deploy.
     *
     * O kit nasce sem tool nenhuma de propósito (não há domínio a consultar ainda). Para
     * registrar a sua:
     *
     *   1. crie a classe da tool (ver `Laravel\Ai\Contracts\Tool` / atributos do SDK),
     *      recebendo o `User` e aplicando as permissões dele NA QUERY;
     *   2. acrescente a fábrica aqui:
     *        'minha_tool' => fn (): MinhaTool => new MinhaTool($this->user),
     *   3. adicione a chave `minha_tool` em `agentes_ia.tools` (painel admin ou seeder).
     *
     * @return list<object>
     */
    public function tools(): iterable
    {
        /** @var array<string, callable(): object> $fabricas */
        $fabricas = [
            // 'minha_tool' => fn (): MinhaTool => new MinhaTool($this->user),
        ];

        return collect($this->agente()->tools ?? [])
            ->filter(fn (string $nome): bool => isset($fabricas[$nome]))
            ->map(fn (string $nome): object => $fabricas[$nome]())
            ->values()
            ->all();
    }
}

<?php

namespace App\Ai\Middleware;

use App\Ai\Agents\AgenteBase;
use Closure;
use Illuminate\Support\Facades\Log;
use Laravel\Ai\Prompts\AgentPrompt;
use Throwable;

/**
 * Auditoria de execução de agentes no canal de log `ai`. Vai por ÚLTIMO no pipeline
 * (`middleware()` do agente devolve `[...guardrails, AiAuditMiddleware]`), então o prompt
 * que chega aqui já passou pelo redator de PII.
 *
 * O TEXTO do prompt nunca é logado em claro: só metadados (tamanho, tokens, latência,
 * provider/modelo). Se o seu projeto precisar do conteúdo para depuração, ligue-o num canal
 * separado e com retenção curta — não aqui.
 *
 * O log `error` (falha de provider) e os `warning` dos guardrails são os insumos estáveis
 * para quem for plugar registro de incidentes.
 */
final class AiAuditMiddleware
{
    public function handle(AgentPrompt $prompt, Closure $next): mixed
    {
        $agente = $prompt->agent;
        $slug   = $agente instanceof AgenteBase ? $agente->slug() : $agente::class;
        $base   = $this->contextoBase($agente, $slug);

        Log::channel('ai')->debug(
            "[AiAuditMiddleware@handle] Execução de agente iniciada | agente: {$slug}",
            [...$base, 'tamanho_prompt' => mb_strlen($prompt->prompt)],
        );

        $inicio = microtime(true);

        try {
            $resposta = $next($prompt);
        } catch (Throwable $e) {
            Log::channel('ai')->error(
                "[AiAuditMiddleware@handle] Falha na execução do agente | agente: {$slug}",
                [...$base, 'exception' => $e->getMessage()],
            );

            throw $e;
        }

        $latenciaMs = (int) round((microtime(true) - $inicio) * 1000);

        Log::channel('ai')->info(
            "[AiAuditMiddleware@handle] Execução de agente concluída | agente: {$slug} - latencia_ms: {$latenciaMs}",
            [
                ...$base,
                // `?? null` interno: em stream o retorno é StreamableAgentResponse, que NÃO
                // tem $toolCalls (laravel/ai 0.10) — acesso direto viraria ErrorException.
                'tools_chamadas'   => ($resposta->toolCalls ?? null)?->map(fn ($call) => $call->name)->all() ?? [],
                'tokens_prompt'    => $resposta->usage->promptTokens ?? null,
                'tokens_resposta'  => $resposta->usage->completionTokens ?? null,
                'tamanho_resposta' => isset($resposta->text) ? mb_strlen((string) $resposta->text) : null,
                'latencia_ms'      => $latenciaMs,
            ],
        );

        return $resposta;
    }

    /**
     * Contexto comum a todos os logs (metadados do agente + provider/modelo).
     *
     * @return array<string, mixed>
     */
    private function contextoBase(object $agente, string $slug): array
    {
        return [
            'agente'       => $slug,
            'versao_paper' => $agente instanceof AgenteBase ? $agente->agente()->versao : null,
            'user_id'      => $agente->user->id ?? null,
            'provider'     => $agente instanceof AgenteBase ? $agente->provider() : null,
            'modelo'       => $agente instanceof AgenteBase ? $agente->model() : null,
        ];
    }
}

